package com.ruoyi.ai.controller;import java.util.Map;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.ruoyi.ai.dto.AiConversationPolicyRequest;import com.ruoyi.ai.service.AiConversationPolicyService;import com.ruoyi.common.annotation.Log;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.common.enums.BusinessType;@RestController @RequestMapping("/ai/admin/policy")public class AiConversationPolicyController{private final AiConversationPolicyService service;public AiConversationPolicyController(AiConversationPolicyService s){service=s;}@PreAuthorize("@ss.hasPermi('ai:policy:view')")@GetMapping public AjaxResult get(){return AjaxResult.success(service.view());}@PreAuthorize("@ss.hasPermi('ai:policy:edit')")@Log(title="AI 会话策略",businessType=BusinessType.UPDATE)@PutMapping public AjaxResult save(@RequestBody AiConversationPolicyRequest r){return AjaxResult.success(service.save(r));}@PreAuthorize("@ss.hasPermi('ai:policy:edit')")@Log(title="AI 会话过期清理",businessType=BusinessType.CLEAN)@PostMapping("/cleanup")public AjaxResult cleanup(){return AjaxResult.success(Map.of("cleaned",service.cleanupExpired()));}}
